#!/usr/bin/env bash
# Block agent modification of forge's generated Vibe guard config and
# instruction surface.
#
# .vibe/ (hooks.toml, forge-roster.json, agents/, prompts/), .agents/ and
# AGENTS.md are generated by install-forge-vibe / forge-gen-vibe-hooks. They
# ARE the safety layer and the instruction surface: an agent that can edit
# hooks.toml can strip `strict` or delete guards, and one that can rewrite
# AGENTS.md or .agents/skills injects instructions into every Vibe session in
# this trusted folder. All are gitignored, so git never restores them.
# Regeneration is a CLI job (install-forge-vibe), never an agent edit.
#
# Fires on:
#   - Edit / Write tools whose file_path (resolved through symlinks) lands
#     under a protected path, including edits[] array entries
#   - Bash commands whose words mention a protected path with a destructive
#     verb or redirect anywhere in the command (relative paths included)
set -e
INPUT=$(cat)

# Protected paths, matched anywhere in the string (not anchored): the whole
# .vibe/ tree, .agents/, and the generated AGENTS.md at repo root.
PROTECTED_RE='(^|[[:space:];|&()<>'"'"'`])(/\.)?\.vibe(/|$)|(^|[[:space:];|&()<>'"'"'`])\.agents(/|$)|(^|[[:space:];|&()<>'"'"'`])AGENTS\.md$'

block() {
    echo "BLOCKED: $1 is forge-generated Vibe guard config / instruction surface. Regenerate with 'install-forge-vibe' (or 'forge-gen-vibe-hooks'); do not edit, delete, or overwrite it by hand or by agent." >&2
    exit 2
}

# --- Edit / Write branch -------------------------------------------------
# Collect every file_path in the payload: top-level and inside edits[].
FILE_PATHS=$(echo "$INPUT" | jq -r '[.tool_input.file_path // empty, (.tool_input.edits // [] | .[].file_path // empty)] | .[]' 2>/dev/null || true)
if [ -n "$FILE_PATHS" ]; then
    while IFS= read -r fp; do
        [ -z "$fp" ] && continue
        # Resolve symlinks so link -> .vibe/hooks.toml cannot slip through.
        resolved=$(realpath "$fp" 2>/dev/null || echo "$fp")
        for p in "$fp" "$resolved"; do
            case "$p" in
                */.vibe/*|*/.agents/*|./.vibe/*|./.agents/*|.vibe/*|.agents/*)
                    block "$fp" ;;
                */AGENTS.md|./AGENTS.md|AGENTS.md)
                    # Only the repo-root AGENTS.md is generated; nested ones
                    # in subdirs are ordinary docs unless they sit at root.
                    case "$p" in
                        AGENTS.md|./AGENTS.md) block "$fp" ;;
                    esac ;;
            esac
        done
    done <<< "$FILE_PATHS"
    exit 0
fi

# --- Bash branch ---------------------------------------------------------
COMMAND=$(echo "$INPUT" | jq -r '.tool_input.command // empty')
[ -z "$COMMAND" ] && exit 0

# Destructive verbs or in-place editors or redirects, each followed
# anywhere later in the command by a protected path. Paths may be relative
# (space-preceded), absolute, or dir-level (.vibe, .vibe/, .agents).
if echo "$COMMAND" | grep -qE '(rm|mv|cp|ln|truncate|sed|perl|tee|python[0-9.]*|node|ruby|php)([[:space:]]|-[a-zA-Z]*[[:space:]])|>|>>' \
   && echo "$COMMAND" | grep -qE '\.vibe(/|[[:space:]]|$)|\.agents(/|[[:space:]]|$)|(^|[[:space:];|&()<>])AGENTS\.md([[:space:];|&()<>]|$)'; then
    block "shell command touching .vibe/, .agents/ or AGENTS.md"
fi
exit 0
